@app.route('/admin/upload', methods=['POST'])
@admin_required
def upload_csv():
    state = request.form.get('state','').lower()
    if state not in ('vic','nsw','qld'):
        return redirect('/admin/upload_page?msg=Invalid+state&msg_type=er')
    f = request.files.get('csvfile')
    if not f:
        return redirect('/admin/upload_page?msg=No+file+selected&msg_type=er')
    try:
        csv_data = f.read().decode('utf-8')
        rows = len([l for l in csv_data.strip().split('\n') if l]) - 1
        db = get_db()
        db.execute('''INSERT INTO property_data (state, csv_data, row_count, uploaded_by)
                      VALUES (?,?,?,?)
                      ON CONFLICT(state) DO UPDATE SET
                      csv_data=excluded.csv_data, row_count=excluded.row_count,
                      uploaded_by=excluded.uploaded_by, uploaded_at=datetime('now')''',
                   (state, csv_data, rows, request.current_user['username']))
        db.commit()
        db.close()
        return redirect('/admin/upload_page?msg='+state.upper()+'+uploaded+successfully+('+str(rows)+'+properties)&msg_type=ok')
    except Exception as e:
        return redirect('/admin/upload_page?msg=Upload+failed:+'+str(e)[:50]+'&msg_type=er')

